var KI={dl:'<path d="M8 2.5v7.5M4.75 7 8 10.25 11.25 7M3 13.5h10"/>',ext:'<path d="M9 2.5h4.5V7M13.5 2.5 7.5 8.5M11.5 9.5v3a1 1 0 01-1 1h-7a1 1 0 01-1-1v-7a1 1 0 011-1h3"/>',cal:'<rect x="2.5" y="3.5" width="11" height="10" rx="1.5"/><path d="M2.5 6.5h11M5.5 2v3M10.5 2v3"/>',chev:'<path d="M4.5 6.5 8 10l3.5-3.5"/>',right:'<path d="M6 3.5 10.5 8 6 12.5"/>',x:'<path d="M4 4l8 8M12 4l-8 8"/>'};
function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var NN={lead:'Step 1 starts once the agreement is signed.',text:'Share it with your counsel, and press Discuss with any questions.',key:'arcsKitNow'};
function kitNowNote(host,d,o){o=o||{};var n=document.createElement('div');n.className='nnote';n.setAttribute('role','note');n.innerHTML='<span class="nnote-pill" aria-hidden="true">Now</span><p><span class="nnote-sr">Now: </span><strong>'+kEsc(d.lead)+'</strong> '+kEsc(d.text)+'</p>';host.appendChild(n);
var k=d.key+':'+Array.from(n.textContent).reduce(function(h,c){return (h*31+c.charCodeAt(0))|0;},7);if(!o.demo){try{if(localStorage.getItem(k)==='1')n.hidden=true;}catch(e){}}
var x=document.createElement('button');x.type='button';x.className='nnote-x';x.setAttribute('aria-label','Dismiss note');x.innerHTML=kIcon('x');x.onclick=function(){n.hidden=true;try{localStorage.setItem(k,'1');}catch(e){}var f=o.focusAfter&&document.querySelector(o.focusAfter);if(f)f.focus();};n.appendChild(x);return n;}
var stg=kSlot();kitNowNote(stg,NN,{focusAfter:'#nn-reset'});var rb=document.createElement('button');rb.type='button';rb.id='nn-reset';rb.className='nnote-x';rb.style.cssText='width:auto;margin:12px 0 0;padding:0 12px;color:var(--cyan)';rb.textContent='Show the note again';rb.onclick=function(){try{Object.keys(localStorage).forEach(function(k){if(k.indexOf(NN.key+':')===0)localStorage.removeItem(k);});}catch(e){}var n=stg.querySelector('.nnote');if(n)n.hidden=false;};stg.appendChild(rb);
STATES.forEach(function(s,i){var el=kSlot(i);if(s[0]==='dismissed'){var p=document.createElement('p');p.style.color='var(--text-secondary)';p.textContent='(nothing renders)';el.appendChild(p);return;}kitNowNote(el,NN,{demo:true});});
